#!/bin/bash
# Pocket Eng installer — https://pocketeng.ai
# curl -fsSL https://pocketeng.ai/install | sh
#
# This installer embeds the pocketeng CLI (v3.2.0) directly so there's
# no second network hop to a GitHub raw URL. Regenerated on every release.
set -e

BINARY="pocketeng"
INSTALL_DIR="/usr/local/bin"
POCKETENG_VERSION="3.2.0"

GREEN='\033[0;32m'
RED='\033[0;31m'
YELLOW='\033[0;33m'
BOLD='\033[1m'
DIM='\033[2m'
NC='\033[0m'

echo ""
echo -e "${BOLD}Pocket Eng${NC} — installing v${POCKETENG_VERSION}..."
echo ""

OS=$(uname -s)
if [ "$OS" != "Darwin" ] && [ "$OS" != "Linux" ]; then
    echo -e "  ${RED}Unsupported OS: $OS${NC}. Pocket Eng supports macOS and Linux."
    exit 1
fi

for cmd in ssh rsync curl python3; do
    if ! command -v "$cmd" >/dev/null 2>&1; then
        echo -e "  ${RED}Missing: $cmd${NC}. Please install it first."
        exit 1
    fi
done

echo -n "  Extracting binary... "
TMP=$(mktemp)
base64 -d > "$TMP" <<'POCKETENG_B64_EOF'

POCKETENG_B64_EOF

if [ ! -s "$TMP" ]; then
    echo -e "${RED}failed${NC}"
    rm -f "$TMP"
    exit 1
fi

chmod +x "$TMP"
echo -e "${GREEN}done${NC}"

echo -n "  Installing to $INSTALL_DIR/$BINARY... "
if [ -w "$INSTALL_DIR" ]; then
    mv "$TMP" "$INSTALL_DIR/$BINARY"
else
    sudo mv "$TMP" "$INSTALL_DIR/$BINARY"
fi
echo -e "${GREEN}done${NC}"

echo ""
if command -v "$BINARY" >/dev/null 2>&1; then
    installed_version=$("$BINARY" version 2>/dev/null || echo "installed")
    echo -e "  ${GREEN}${BOLD}$installed_version${NC}"
    echo ""
    echo -e "  Next steps:"
    echo -e "    1. ${BOLD}pocketeng login${NC}                    sign in and sync workspaces"
    echo -e "    2. ${BOLD}cd <your project>${NC}"
    echo -e "    3. ${BOLD}pocketeng sync${NC}                     mirror code + session to the cloud"
    echo ""
else
    echo -e "  ${YELLOW}Installed to $INSTALL_DIR/$BINARY but it's not on your PATH.${NC}"
    echo -e "  Add $INSTALL_DIR to your PATH or restart your shell."
fi
